 ## [Unreleased]

+### Added
+
+- `merge_objects`: merge a duplicate into the record to keep, for
+  people, families, events, places, sources, citations, notes, media and
+  repositories, through Gramps Web's merge endpoint (API 3.15 or newer).
+  Gramps merges them in one transaction: the duplicate's details and
+  every link to it move to the kept record, and the duplicate is
+  deleted. The kept record keeps its own fields; a merged person keeps
+  the other name as an alternate name. Merging people also merges a
+  family with the same partner unless `mergeFamilies` is false, and
+  merging families merges their different fathers and mothers, keeping
+  `fatherHandle` and `motherHandle` when given. Spouses and a parent
+  with their child are refused before the user is asked. The user
+  confirms the merge in a dialog that names both records, as for
+  `delete_object` and `undo_change`, and the reply gives the
+  transaction that `undo_change` takes to restore the duplicate.
+
 ### Changed

 - `create_family` says what it returns: the handle, Gramps ID and stored"},{"sha":"06c72d73dc545750d00e5cc7ec278077f1575130","filename":"GrampsWeb.Mcp.IntegrationTests/MergeTests.cs","status":"added","additions":182,"deletions":0,"changes":182,"blob_url":"https://github.com/Scormave/gramps-web-mcp/blob/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.IntegrationTests%2FMergeTests.cs","raw_url":"https://github.com/Scormave/gramps-web-mcp/raw/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.IntegrationTests%2FMergeTests.cs","contents_url":"https://api.github.com/repos/Scormave/gramps-web-mcp/contents/GrampsWeb.Mcp.IntegrationTests%2FMergeTests.cs?ref=65d1f19e7d525f388b9852baeffe13008a9cfc8a","patch":"@@ -0,0 +1,182 @@
+using Xunit;
+
+namespace GrampsWeb.Mcp.IntegrationTests;
+
+/// <summary>
+/// merge_objects against a real Gramps Web. The test server has no confirmation dialog, so each merge runs
+/// without a question.
+/// </summary>
+[Collection(GrampsWebCollection.Name)]
+public sealed class MergeTests(GrampsWebFixture gramps)
+{
+    private McpSession Session => gramps.Session;
+
+    [IntegrationFact]
+    public async Task Merge_OfTwoPeople_MovesTheLinks_AndUndoRestoresTheDuplicate()
+    {
+        var surname = TestNames.Surname();
+        var keep = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Anna", surname },
+            gender = "female"
+        });
+        var birth = await Session.CreateAsync("create_event", new { eventType = "Birth", date = "1890" });
+        var duplicate = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Anya", surname },
+            gender = "female",
+            eventRefs = new[] { $"{birth.Handle}::Primary" }
+        });
+
+        var merged = await Session.CallAsync("merge_objects", new
+        {
+            objectType = "person",
+            keepHandle = keep.Handle,
+            duplicateHandle = duplicate.Handle
+        });
+
+        Assert.Equal("merged", McpSession.Header(merged, "action"));
+        Assert.Equal(keep.Handle, McpSession.Header(merged, "handle"));
+        Assert.Equal(duplicate.GrampsId, McpSession.Header(merged, "duplicate_gramps_id"));
+        var transaction = int.Parse(McpSession.Header(merged, "transaction"));
+        var changes = await Session.CallAsync("get_recent_changes", new { limit = 1 });
+        Assert.Contains("Merge Person", changes);
+        Assert.Contains($"[transaction: {transaction}]", changes);
+        var stored = await GetPersonAsync(keep.Handle);
+        Assert.Contains($"Primary name [Birth Name]: Anna {surname}", stored);
+        Assert.Contains($"[Birth Name] Anya {surname}", stored);
+        Assert.Contains($"Merged Gramps ID: {duplicate.GrampsId}", stored);
+        Assert.Contains($"Birth: 1890 [Primary] [handle: {birth.Handle}]", stored);
+        Assert.Contains($"Person not found: {duplicate.Handle}", await GetPersonAsync(duplicate.Handle));
+
+        var undone = await Session.CallAsync("undo_change", new { transactionId = transaction });
+        if (UndoTests.ImageBeforeDeletionFix())
+        {
+            Assert.Equal("refused", McpSession.Header(undone, "action"));
+            undone = await Session.CallAsync("undo_change", new { transactionId = transaction, force = true });
+        }
+
+        Assert.Equal("undone", McpSession.Header(undone, "action"));
+        Assert.Contains($"Restored the deleted Person {duplicate.GrampsId}: ", undone);
+        var restored = await GetPersonAsync(duplicate.Handle);
+        Assert.Contains($"Primary name [Birth Name]: Anya {surname}", restored);
+        Assert.Contains(birth.Handle, restored);
+        Assert.DoesNotContain("Merged Gramps ID", await GetPersonAsync(keep.Handle));
+    }
+
+    [IntegrationFact]
+    public async Task Merge_OfSpouses_IsRefused_AndChangesNothing()
+    {
+        var surname = TestNames.Surname();
+        var husband = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Ivan", surname },
+            gender = "male"
+        });
+        var wife = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Anna", surname },
+            gender = "female"
+        });
+        await Session.CreateAsync("create_family", new { fatherHandle = husband.Handle, motherHandle = wife.Handle });
+
+        var refused = await Session.CallAsync("merge_objects", new
+        {
+            objectType = "person",
+            keepHandle = husband.Handle,
+            duplicateHandle = wife.Handle
+        });
+
+        Assert.Equal("refused", McpSession.Header(refused, "action"));
+        Assert.Contains("spouses cannot be merged", refused);
+        Assert.Contains(wife.Handle, await GetPersonAsync(wife.Handle));
+        Assert.DoesNotContain("Merged Gramps ID", await GetPersonAsync(husband.Handle));
+    }
+
+    [IntegrationFact]
+    public async Task Merge_OfTwoFamilies_JoinsTheFathers_AndMovesTheChildren()
+    {
+        var surname = TestNames.Surname();
+        var father = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Ivan", surname },
+            gender = "male"
+        });
+        var mother = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Anna", surname },
+            gender = "female"
+        });
+        var keep = await Session.CreateAsync("create_family", new { fatherHandle = father.Handle, motherHandle = mother.Handle });
+        var otherFather = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Ioann", surname },
+            gender = "male"
+        });
+        var son = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Petr", surname },
+            gender = "male"
+        });
+        var duplicate = await Session.CreateAsync("create_family", new
+        {
+            fatherHandle = otherFather.Handle,
+            relationshipType = "Married",
+            childRefs = new[] { $"{son.Handle}::Birth" }
+        });
+
+        var merged = await Session.CallAsync("merge_objects", new
+        {
+            objectType = "family",
+            keepHandle = keep.Handle,
+            duplicateHandle = duplicate.Handle
+        });
+
+        Assert.Equal("merged", McpSession.Header(merged, "action"));
+        Assert.Contains("The same merge also joined and deleted 1 person.", merged);
+        var family = await Session.CallAsync("get_object", new { objectType = "family", identifier = keep.Handle, extended = true });
+        Assert.Contains($"[handle: {father.Handle}]", family);
+        Assert.Contains($"[handle: {mother.Handle}]", family);
+        Assert.Contains($"[handle: {son.Handle}]", family);
+        // The kept family's type was Unknown, so it takes the duplicate's.
+        Assert.Contains("Relationship: Married", family);
+        Assert.Contains($"Family not found: {duplicate.Handle}",
+            await Session.CallAsync("get_object", new { objectType = "family", identifier = duplicate.Handle }));
+        Assert.Contains($"Person not found: {otherFather.Handle}", await GetPersonAsync(otherFather.Handle));
+        Assert.Contains($"Merged Gramps ID: {otherFather.GrampsId}", await GetPersonAsync(father.Handle));
+    }
+
+    [IntegrationFact]
+    public async Task Merge_OfTwoNotes_KeepsTheKeptText_AndMovesTheLinks()
+    {
+        var keptText = TestNames.Unique("kept");
+        var droppedText = TestNames.Unique("dropped");
+        var keep = await Session.CreateAsync("create_note", new { text = keptText });
+        var duplicate = await Session.CreateAsync("create_note", new { text = droppedText });
+        var person = await Session.CreateAsync("create_person", new
+        {
+            primaryName = new { first = "Olga", surname = TestNames.Surname() },
+            noteHandles = new[] { duplicate.Handle }
+        });
+
+        var merged = await Session.CallAsync("merge_objects", new
+        {
+            objectType = "note",
+            keepHandle = keep.GrampsId,
+            duplicateHandle = duplicate.GrampsId
+        });
+
+        Assert.Equal("merged", McpSession.Header(merged, "action"));
+        Assert.Equal(keep.Handle, McpSession.Header(merged, "handle"));
+        Assert.Equal(duplicate.Handle, McpSession.Header(merged, "duplicate_handle"));
+        var note = await Session.CallAsync("get_object", new { objectType = "note", identifier = keep.Handle });
+        Assert.Contains(keptText, note);
+        Assert.DoesNotContain(droppedText, note);
+        Assert.Contains($"[handle: {person.Handle}]", note);
+        Assert.Contains($"Note not found: {duplicate.Handle}",
+            await Session.CallAsync("get_object", new { objectType = "note", identifier = duplicate.Handle }));
+    }
+
+    private Task<string> GetPersonAsync(string handle) =>
+        Session.CallAsync("get_object", new { objectType = "person", identifier = handle, extended = true });
+}"},{"sha":"5e319ff642e27285724a2b8038b2b2634392916d","filename":"GrampsWeb.Mcp.IntegrationTests/UndoTests.cs","status":"modified","additions":1,"deletions":1,"changes":2,"blob_url":"https://github.com/Scormave/gramps-web-mcp/blob/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.IntegrationTests%2FUndoTests.cs","raw_url":"https://github.com/Scormave/gramps-web-mcp/raw/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.IntegrationTests%2FUndoTests.cs","contents_url":"https://api.github.com/repos/Scormave/gramps-web-mcp/contents/GrampsWeb.Mcp.IntegrationTests%2FUndoTests.cs?ref=65d1f19e7d525f388b9852baeffe13008a9cfc8a","patch":"@@ -136,7 +136,7 @@ private async Task<int> LatestTransactionAsync()
     }

     /// <summary>Gramps Web images before 26.10 (API 3.23) undo a deletion only with force.</summary>
-    private static bool ImageBeforeDeletionFix()
+    internal static bool ImageBeforeDeletionFix()
     {
         var tag = GrampsWebImage.Name.Split(':').LastOrDefault() ?? "";
         return Version.TryParse(tag, out var version) && version < new Version(26, 10);"},{"sha":"6b886e28cc7edb9cc852604eea7c9af13257c3b7","filename":"GrampsWeb.Mcp.Tests/UnitTests/MergeObjectsTests.cs","status":"added","additions":423,"deletions":0,"changes":423,"blob_url":"https://github.com/Scormave/gramps-web-mcp/blob/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.Tests%2FUnitTests%2FMergeObjectsTests.cs","raw_url":"https://github.com/Scormave/gramps-web-mcp/raw/65d1f19e7d525f388b9852baeffe13008a9cfc8a/GrampsWeb.Mcp.Tests%2FUnitTests%2FMergeObjectsTests.cs","contents_url":"https://api.github.com/repos/Scormave/gramps-web-mcp/contents/GrampsWeb.Mcp.Tests%2FUnitTests%2FMergeObjectsTests.cs?ref=65d1f19e7d525f388b9852baeffe13008a9cfc8a","patch":"@@ -0,0 +1,423 @@
+using System.Net;
+using System.Text;
+using GrampsWeb.Mcp.Client;
+using GrampsWeb.Mcp.Config;
+using GrampsWeb.Mcp.Tools;
+using Microsoft.Extensions.Logging.Abstractions;
+using ModelContextProtocol;
+using Xunit;
+
+namespace GrampsWeb.Mcp.Tests.UnitTests;
+
+/// <summary>merge_objects asks the user, then has Gramps Web merge the duplicate into the record to keep.</summary>
+public class MergeObjectsTests
+{
+    private const string NoteMerge = "POST /api/notes/n1/merge/n2";
+    private const string HistoryPath = "/api/transactions/history/?page=1&pagesize=10&sort=-id";
+
+    [Fact]
+    public async Task Merge_AsksTheUser_ThenMerges()
+    {
+        using var server = NoteServer();
+        server.Get("/api/notes/?handles=n1,n2&page=1&pagesize=2",
+            """[{"handle": "n1", "gramps_id": "N0001", "type": "General", "text": {"string": "Born in Tver"}},""" +
+            """ {"handle": "n2", "gramps_id": "N0002", "type": "General", "text": {"string": "Born at Tver"}}]""");
+        var user = new FakeConfirmation(ConfirmationAnswer.Confirmed);
+
+        var result = await Merge(server, user);
+
+        var question = Assert.Single(user.Questions).ReplaceLineEndings("\n");
+        Assert.StartsWith(
+            "Merge Note N0002 into N0001?\n\n  • Keep N0001: [General] Born in Tver\n" +
+            "  • Merge into it and delete N0002: [General] Born at Tver\n\nThe kept note keeps its text and type",
+            question);
+        Assert.EndsWith("\n\nThe change history keeps the duplicate: undo_change can undo the merge later.", question);
+        Assert.Contains(NoteMerge, server.Requests);
+        Assert.Equal("{}", server.Bodies[NoteMerge]);
+        Assert.StartsWith(
+            "---\ntype: Note\naction: merged\nhandle: n1\ngramps_id: N0001\nduplicate_handle: n2\n" +
+            "duplicate_gramps_id: N0002\ntransaction: 41\n---\nN0002 was merged into N0001 and deleted",
+            result);
+        Assert.Contains("undo_change(transactionId: 41)", result);
+        Assert.DoesNotContain("also joined", result);
+    }
+
+    [Theory]
+    [InlineData("Declined", "declined", "Do not call again unless the user asks again")]
+    [InlineData("Cancelled", "cancelled", "Ask the user in chat before calling again")]
+    [InlineData("Unavailable", "not_confirmed", "GRAMPS_CONFIRMATION=required")]
+    [InlineData("Failed", "not_confirmed", "could not show the confirmation dialog")]
+    public async Task Merge_WithoutConfirmation_MergesNothing(string answer, string action, string reason)
+    {
+        using var server = NoteServer();
+
+        var result = await Merge(server, new FakeConfirmation(Enum.Parse<ConfirmationAnswer>(answer)));
+
+        Assert.StartsWith($"---\ntype: Note\naction: {action}\nhandle: n1\nduplicate_handle: n2\n---\n", result);
+        Assert.Contains(reason, result);
+        Assert.DoesNotContain(server.Requests, r => r.StartsWith("POST", StringComparison.Ordinal));
+    }
+
+    [Fact]
+    public async Task Merge_WhenARecordChangesWhileTheUserDecides_MergesNothing()
+    {
+        using var server = NoteServer();
+        var user = new FakeConfirmation(ConfirmationAnswer.Confirmed,
+            whileDeciding: () => server.Get("/api/notes/n2", Note("n2", "N0002", change: 1700000999)));
+
+        var result = await Merge(server, user);
+
+        Assert.StartsWith("---\ntype: Note\naction: refused\nhandle: n1\nduplicate_handle: n2\n---\n", result);
+        Assert.Contains("changed while the user was deciding", result);
+        Assert.DoesNotContain(server.Requests, r => r.StartsWith("POST", StringComparison.Ordinal));
+    }
+
+    [Fact]
+    public async Task Merge_WithoutDialog_MergesWithoutAsking()
+    {
+        using var server = NoteServer();
+
+        var result = await MergeTools.MergeObjectsAsync("note", "n1", "n2", true, null, null,
+            CreateClient(server), UserConfirmation.None);
+
+        Assert.Contains("action: merged", result);
+        Assert.Contains(NoteMerge, server.Requests);
+    }
+
+    [Fact]
+    public async Task Merge_OfPartners_IsRefusedBeforeAsking()
+    {
+        using var server = PeopleServer(keepFamilies: """["f1"]""", duplicateFamilies: """["f1"]""");
+        var user = new FakeConfirmation(ConfirmationAnswer.Confirmed);
+
+        var result = await MergePeople(server, user);
+
+        Assert.StartsWith("---\ntype: Person\naction: refused\nhandle: p1\nduplicate_handle: p2\n---\n", result);
+        Assert.Contains("spouses cannot be merged", result);
+        Assert.Contains("Nothing was changed.", result);
+        Assert.Empty(user.Questions);
+        Assert.DoesNotContain(server.Requests, r => r.StartsWith("POST", StringComparison.Ordinal));
+    }
+
+    [Fact]
+    public async Task Merge_OfParentAndChild_IsRefusedBeforeAsking()
+    {
+        using var server = PeopleServer(keepFamilies: """["f1"]""", duplicateParents: """["f1"]""");
+        var user = new FakeConfirmation(ConfirmationAnswer.Confirmed);
+
+        var result = await MergePeople(server, user);
+
+        Assert.Contains("action: refused", result);
+        Assert.Contains("a parent and child cannot be merged", result);
+        Assert.Empty(user.Questions);
+        Assert.DoesNotContain(server.Requests, r => r.StartsWith("POST", StringComparison.Ordinal));
+    }
+
+    [Theory]
+    [InlineData(true, """{"family_merger":true}""")]
+    [InlineData(false, """{"family_merger":false}""")]
+    public async Task Merge_OfPeople_SendsTheFamilyChoice(bool mergeFamilies, string body)
+    {
+        using var server = PeopleServer();
+        server.Get(HistoryPath,
+            """[{"id": 7, "description": "Merge Person", "changes": [""" +
+            """{"obj_class": "Person", "trans_type": 2, "obj_handle": "p2"},""" +
+            """{"obj_class": "Family", "trans_type": 2, "obj_handle": "f2"},""" +
+            """{"obj_class": "7", "trans_type": 2, "obj_handle": "f3"},""" +
+            """{"obj_class": "Person", "trans_type": 1, "obj_handle": "p1"}]}]""");
